import React from "react";
import { HashRouter, Routes, Route } from "react-router-dom"
import "./App.css";
import BlurHome from "./defaultresort/mainhome/blurHome";
// import BlurredList from "./defaultresort/mainhome/blurredlist";
const LazyMainHome = React.lazy( () => import("./defaultresort/mainhome/mainhome") )
// const LazyAllRooms = React.lazy( () => import("./roomslist/allrooms"))


function App() {
  return (
    <HashRouter>

      <Routes>
        <Route path="/" element={
          <React.Suspense fallback={<BlurHome />} >
            <LazyMainHome />
          </React.Suspense>
        } />

      </Routes>
    </HashRouter>
  );
}

export default App;
